mapper.select:
SELECT id, name, biz_type, description, enabled, nodes,
       organization_id, create_user, update_user, create_time, update_time
FROM crm_approval_template
WHERE organization_id = #{organizationId}

    AND (name LIKE CONCAT('%', #{keyword}, '%')
         OR description LIKE CONCAT('%', #{keyword}, '%'))


    AND biz_type = #{bizType}


    AND enabled = #{enabled}

ORDER BY create_time DESC
